-- generated by scripts/matches-sql.mjs on 2026-09-10T10:13:10.776Z
-- 144 matches, phases: league

  values ('champion', 'Champions League winner', least(now(), '2026-10-13T16:45:00+00:00'::timestamptz - interval '1 minute'), '2026-10-13T16:45:00+00:00')
  on conflict (phase) do nothing;
  values ('scorer', 'Gólkirály (top scorer)', least(now(), '2026-10-13T16:45:00+00:00'::timestamptz - interval '1 minute'), '2026-10-13T16:45:00+00:00')
  on conflict (phase) do nothing;
  values ('league', 'League phase', least(now(), '2026-10-13T16:45:00+00:00'::timestamptz - interval '1 minute'), '2026-10-13T16:45:00+00:00')
  on conflict (phase) do nothing;

-- Matches (upsert by num). Kickoffs move with ESPN; picks stay keyed by num.
on conflict (num) do update set
  espn = excluded.espn, phase = excluded.phase, round = excluded.round,
  kickoff = excluded.kickoff, team1 = excluded.team1, team2 = excluded.team2;
